export function createOptimisticStore(initialState) {
  let base = initialState;
  let visible = initialState;
  let pending = new Map();
  const subscriptions = new Set();

  function replay(state, changes) {
    for (const update of changes.values()) {
      state = update(state);
    }
    return state;
  }

  function notify() {
    // Snapshot subscriptions so removals cannot disrupt this notification.
    const snapshot = Array.from(subscriptions);
    for (const { listener } of snapshot) {
      try {
        listener();
      } catch {
        // A failing listener must not prevent other listeners from running.
      }
    }
  }

  return {
    getState() {
      return visible;
    },

    apply(id, update) {
      if (pending.has(id)) {
        throw new Error("A pending change with this id already exists.");
      }

      const nextVisible = update(visible);
      pending.set(id, update);
      visible = nextVisible;
      notify();
    },

    confirm(id) {
      if (!pending.has(id)) {
        return false;
      }

      const update = pending.get(id);
      const nextPending = new Map(pending);
      nextPending.delete(id);

      // Calculate everything before committing to avoid partial changes.
      const nextBase = update(base);
      const nextVisible = replay(nextBase, nextPending);

      base = nextBase;
      pending = nextPending;
      visible = nextVisible;
      notify();
      return true;
    },

    rollback(id) {
      if (!pending.has(id)) {
        return false;
      }

      const nextPending = new Map(pending);
      nextPending.delete(id);
      const nextVisible = replay(base, nextPending);

      pending = nextPending;
      visible = nextVisible;
      notify();
      return true;
    },

    subscribe(listener) {
      const subscription = { listener };
      subscriptions.add(subscription);

      return () => {
        subscriptions.delete(subscription);
      };
    }
  };
}
